Content.Interface:
FUNCTION_BLOCK FN_GW_GCS
VAR
	LAST_IOSERVER_ANALOG:ARRAY[1..100] OF REAL;
	LAST_IOSERVER_BOOL	:ARRAY[1..100] OF BOOL;
	I					:INT;
	GW_GCS_BOOL			:ARRAY[1..100] OF TP;
	ANALOG_DATA_CHANGED	:BOOL;
	BOOL_DATA_CHANGED	:BOOL;
	LAST_GW_GCS_MAP		:GW_TO_GCS;
	WRITE_TIMER			:TP;
	
END_VAR
VAR_INPUT
	GW_GCS					:GW_TO_GCS;
	IOSERVER_ANALOG			:ARRAY [1..100] OF REAL;
	IOSERVER_BOOL			:ARRAY[1..100] OF BOOL;
	GCS_INIT_COMPLETE		:BOOL;
	ENABLE					:BOOL;
END_VAR

VAR_OUTPUT
	NGVL_GW_GCS:GW_TO_GCS;
	
END_VAR

Content.Implementation:
IF (ENABLE) THEN
		
	
	FOR I:= 1 TO 50 DO
		LAST_GW_GCS_MAP.AI[I]:=GW_GCS.AI[I];
		
	END_FOR
	LAST_GW_GCS_MAP.DWORD1:= GW_GCS.DWORD1;
	LAST_GW_GCS_MAP.DWORD2:= GW_GCS.DWORD2;
	LAST_GW_GCS_MAP.DWORD3:= GW_GCS.DWORD3;
	
	
	FOR i:=1 TO 100 DO
		IF (LAST_IOSERVER_ANALOG[I] <> IOSERVER_ANALOG[I]) AND GCS_INIT_COMPLETE  THEN
			GW_GCS.AI[I]:= IOSERVER_ANALOG[I];		
		END_IF
		
		IF GCS_INIT_COMPLETE THEN
			GW_GCS_BOOL[I](IN:=IOSERVER_BOOL[I] ,PT:=T#1S);
		END_IF
	END_FOR
	
	LAST_IOSERVER_ANALOG	:= IOSERVER_ANALOG;
	LAST_IOSERVER_BOOL		:= IOSERVER_BOOL;
	
	GW_GCS.DWORD1.0:=GW_GCS_BOOL[1].Q;
	GW_GCS.DWORD1.1:=GW_GCS_BOOL[2].Q;
	GW_GCS.DWORD1.2:=GW_GCS_BOOL[3].Q;
	GW_GCS.DWORD1.3:=GW_GCS_BOOL[4].Q;
	GW_GCS.DWORD1.4:=GW_GCS_BOOL[5].Q;
	GW_GCS.DWORD1.5:=GW_GCS_BOOL[6].Q;
	GW_GCS.DWORD1.6:=GW_GCS_BOOL[7].Q;
	GW_GCS.DWORD1.7:=GW_GCS_BOOL[8].Q;
	GW_GCS.DWORD1.8:=GW_GCS_BOOL[9].Q;
	GW_GCS.DWORD1.9:=GW_GCS_BOOL[10].Q;
	GW_GCS.DWORD1.10:=GW_GCS_BOOL[11].Q;
	GW_GCS.DWORD1.11:=GW_GCS_BOOL[12].Q;
	GW_GCS.DWORD1.12:=GW_GCS_BOOL[13].Q;
	GW_GCS.DWORD1.13:=GW_GCS_BOOL[14].Q;
	GW_GCS.DWORD1.14:=GW_GCS_BOOL[15].Q;
	GW_GCS.DWORD1.15:=GW_GCS_BOOL[16].Q;
	GW_GCS.DWORD1.16:=GW_GCS_BOOL[17].Q;
	GW_GCS.DWORD1.17:=GW_GCS_BOOL[18].Q;
	GW_GCS.DWORD1.18:=GW_GCS_BOOL[19].Q;
	GW_GCS.DWORD1.19:=GW_GCS_BOOL[20].Q;
	GW_GCS.DWORD1.20:=GW_GCS_BOOL[21].Q;
	GW_GCS.DWORD1.21:=GW_GCS_BOOL[22].Q;
	GW_GCS.DWORD1.22:=GW_GCS_BOOL[23].Q;
	GW_GCS.DWORD1.23:=GW_GCS_BOOL[24].Q;
	GW_GCS.DWORD1.24:=GW_GCS_BOOL[25].Q;
	GW_GCS.DWORD1.25:=GW_GCS_BOOL[26].Q;
	GW_GCS.DWORD1.26:=GW_GCS_BOOL[27].Q;
	GW_GCS.DWORD1.27:=GW_GCS_BOOL[28].Q;
	GW_GCS.DWORD1.28:=GW_GCS_BOOL[29].Q;
	GW_GCS.DWORD1.29:=GW_GCS_BOOL[30].Q;
	GW_GCS.DWORD1.30:=GW_GCS_BOOL[31].Q;
	GW_GCS.DWORD1.31:=GW_GCS_BOOL[32].Q;
	GW_GCS.DWORD2.0:=GW_GCS_BOOL[33].Q;
	GW_GCS.DWORD2.1:=GW_GCS_BOOL[34].Q;
	GW_GCS.DWORD2.2:=GW_GCS_BOOL[35].Q;
	GW_GCS.DWORD2.3:=GW_GCS_BOOL[36].Q;
