	GW_GCS.DWORD2.6:=GW_GCS_BOOL[39].Q;
	GW_GCS.DWORD2.7:=GW_GCS_BOOL[40].Q;
	GW_GCS.DWORD2.8:=GW_GCS_BOOL[41].Q;
	GW_GCS.DWORD2.9:=GW_GCS_BOOL[42].Q;
	GW_GCS.DWORD2.10:=GW_GCS_BOOL[43].Q;
