	GW_GCS.DWORD2.13:=GW_GCS_BOOL[46].Q;
	GW_GCS.DWORD2.14:=GW_GCS_BOOL[47].Q;
	GW_GCS.DWORD2.15:=GW_GCS_BOOL[48].Q;
	GW_GCS.DWORD2.16:=GW_GCS_BOOL[49].Q;
	GW_GCS.DWORD2.17:=GW_GCS_BOOL[50].Q;
	GW_GCS.DWORD2.18:=GW_GCS_BOOL[51].Q;
