	GW_GCS.DWORD3.3:=GW_GCS_BOOL[68].Q;
	GW_GCS.DWORD3.4:=GW_GCS_BOOL[69].Q;
	GW_GCS.DWORD3.5:=GW_GCS_BOOL[70].Q;
	GW_GCS.DWORD3.6:=GW_GCS_BOOL[71].Q;
	GW_GCS.DWORD3.7:=GW_GCS_BOOL[72].Q;
	GW_GCS.DWORD3.8:=GW_GCS_BOOL[73].Q;
	GW_GCS.DWORD3.9:=GW_GCS_BOOL[74].Q;
	GW_GCS.DWORD3.10:=GW_GCS_BOOL[75].Q;
	GW_GCS.DWORD3.11:=GW_GCS_BOOL[76].Q;
	GW_GCS.DWORD3.12:=GW_GCS_BOOL[77].Q;
	GW_GCS.DWORD3.13:=GW_GCS_BOOL[78].Q;

	
	ANALOG_DATA_CHANGED:=FALSE;
	BOOL_DATA_CHANGED:=FALSE;
	FOR i:=1 TO 50 DO
		ANALOG_DATA_CHANGED	:= (GW_GCS.AI[I] <> LAST_GW_GCS_MAP.AI[I]) OR ANALOG_DATA_CHANGED;
	END_FOR
	
	BOOL_DATA_CHANGED:= (GW_GCS.DWORD1 <> LAST_GW_GCS_MAP.DWORD1) OR (GW_GCS.DWORD2 <> LAST_GW_GCS_MAP.DWORD2) OR (GW_GCS.DWORD3 <> LAST_GW_GCS_MAP.DWORD3) OR BOOL_DATA_CHANGED;
	
	WRITE_TIMER.IN:= ANALOG_DATA_CHANGED;
	WRITE_TIMER.PT:= T#500mS;
	WRITE_TIMER();
	
	
	GW_GCS.DWORD3.14 := WRITE_TIMER.Q;
	NGVL_GW_GCS:=GW_GCS;
END_IF
